import { getRiwayatSurveilans } from "@/services/surveilans";
import { 
  FileEdit, 
  Calendar, 
  ChevronLeft, 
  ChevronRight,
  Database,
  Lock
} from "lucide-react";
import Link from "next/link";
import DeleteButton from "./DeleteButton";

export const dynamic = "force-dynamic";

interface Props {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}

export default async function RiwayatPage({ searchParams }: Props) {
  const sParams = await searchParams;
  const currentPage = Number(sParams.page) || 1;
  const currentLimit = Number(sParams.limit) || 10; // Default 10 data

  // Ambil data dari server sesuai limit yang dipilih
  const { data: allRiwayat, total: totalDatabase } = await getRiwayatSurveilans(500); // Ambil cadangan data cukup banyak
  
  const totalData = allRiwayat.length;
  const totalPages = Math.ceil(totalData / currentLimit);
  const startIndex = (currentPage - 1) * currentLimit;
  const paginatedData = allRiwayat.slice(startIndex, startIndex + currentLimit);

 return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div>
          <h1 className="text-lg font-bold text-slate-800">Riwayat Surveilans</h1>
          <p className="text-xs text-slate-400">Total {totalDatabase} Laporan Terdata</p>
        </div>

        {/* FITUR PILIH VIEW DATA (10, 50, 100) */}
        <div className="flex items-center gap-2 border px-3 py-1.5 rounded-xl bg-slate-50">
          <span className="text-[10px] font-bold text-slate-400 uppercase">View:</span>
          <select 
            defaultValue={currentLimit}
            onChange={(e) => window.location.href = `/dashboard/perawat/riwayat?page=1&limit=${e.target.value}`}
            className="bg-transparent text-xs font-bold text-blue-600 outline-none cursor-pointer"
          >
            <option value="10">10</option>
            <option value="50">50</option>
            <option value="100">100</option>
          </select>
        </div>
      </div>

      {/* TABEL DATA (paginatedData) ... (kode tabel tetap sama) */}

      {/* FOOTER NAVIGASI SEPERTI GAMBAR CONTOH */}
      <div className="p-4 bg-slate-900 text-white rounded-b-3xl flex justify-between items-center">
        <div className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-widest">
           <div className="flex gap-2">
             <Link href={`?page=1&limit=${currentLimit}`} className="hover:text-blue-400">First</Link>
             <Link href={`?page=${Math.max(1, currentPage - 1)}&limit=${currentLimit}`} className="hover:text-blue-400">Prev</Link>
           </div>
           <span>Page {currentPage} of {totalPages}</span>
           <div className="flex gap-2">
             <Link href={`?page=${Math.min(totalPages, currentPage + 1)}&limit=${currentLimit}`} className="hover:text-blue-400">Next</Link>
             <Link href={`?page=${totalPages}&limit=${currentLimit}`} className="hover:text-blue-400">Last</Link>
           </div>
        </div>

        <div className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
          Viewing {startIndex + 1} - {Math.min(startIndex + currentLimit, totalData)} of {totalData}
        </div>
      </div>
    </div>
  );
}